<style>
:root{--brand:#8bd10f;--ink:#0b1420;--muted:#68778a;--line:#e0e7ef}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:#f5f8fb;font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;color:var(--ink);display:grid;grid-template-columns:minmax(360px,.85fr) minmax(480px,1.15fr)}.visual{position:relative;background:linear-gradient(155deg,#0b1522,#142742);padding:46px;color:#fff;overflow:hidden;display:flex;flex-direction:column;justify-content:space-between}.visual::before,.visual::after{content:"";position:absolute;border-radius:50%;pointer-events:none}.visual::before{width:430px;height:430px;right:-170px;top:8%;background:radial-gradient(circle,rgba(139,209,15,.22),transparent 68%)}.visual::after{width:360px;height:360px;left:-170px;bottom:-120px;background:radial-gradient(circle,rgba(122,179,255,.12),transparent 68%)}.brand{position:relative;display:flex;align-items:center;gap:13px}.logo{width:48px;height:48px;border-radius:15px;background:linear-gradient(145deg,#a8e32e,#74bd00);display:grid;place-items:center;color:#0d1723;font-size:18px;font-weight:950;box-shadow:0 14px 30px rgba(139,209,15,.2)}.brand-name{font-size:21px;font-weight:900;letter-spacing:-.035em}.brand-name b{color:#a6df31}.brand-sub{font-size:10px;font-weight:800;color:#90a3b8;letter-spacing:.08em;margin-top:2px}.hero{position:relative;max-width:460px}.eyebrow{display:inline-flex;padding:6px 9px;border:1px solid rgba(167,225,46,.25);background:rgba(139,209,15,.09);color:#b7e962;border-radius:999px;font-size:10px;font-weight:850;letter-spacing:.07em;text-transform:uppercase}.hero h1{font-size:43px;line-height:1.05;letter-spacing:-.05em;margin:18px 0 15px}.hero p{color:#aab8c9;line-height:1.7;font-size:14px;max-width:420px}.features{display:grid;gap:10px;margin-top:28px}.feature{display:flex;gap:10px;align-items:center;color:#c9d4df;font-size:12px;font-weight:650}.check{width:22px;height:22px;border-radius:50%;background:rgba(139,209,15,.14);color:#9edb28;display:grid;place-items:center;font-weight:900}.foot{position:relative;color:#70859d;font-size:10px}.form-side{display:grid;place-items:center;padding:34px}.card{width:min(430px,100%);background:#fff;border:1px solid var(--line);border-radius:24px;padding:32px;box-shadow:0 25px 70px rgba(12,27,45,.09)}.card h2{margin:0;font-size:27px;letter-spacing:-.035em}.card>p{color:var(--muted);line-height:1.55;font-size:13px;margin:8px 0 24px}.field{margin-top:15px}.field label{display:block;font-size:11px;font-weight:850;color:#3b4a5e;margin-bottom:7px}.input{width:100%;height:44px;border:1px solid var(--line);border-radius:11px;padding:0 13px;font:inherit;outline:0;transition:.18s;background:#fbfcfd}.input:focus{background:#fff;border-color:#afd65e;box-shadow:0 0 0 4px rgba(139,209,15,.1)}.remember{display:flex;gap:8px;align-items:center;margin:17px 0;color:#5d6d80;font-size:12px;font-weight:650}.remember input{accent-color:#79bd00;width:16px;height:16px}.btn{width:100%;border:0;border-radius:11px;padding:13px;background:linear-gradient(180deg,#94d919,#78be00);color:#173100;font-weight:900;font-size:13px;cursor:pointer;box-shadow:0 9px 20px rgba(117,186,0,.2);transition:.17s}.btn:hover{transform:translateY(-1px);box-shadow:0 12px 25px rgba(117,186,0,.25)}.error{background:#fff2f2;color:#9b3434;border:1px solid #ffd8d8;border-radius:11px;padding:11px 12px;margin:0 0 14px;font-size:12px}.hint{text-align:center;margin-top:20px;color:#9aa7b6;font-size:10px}@media(max-width:850px){body{display:block}.visual{min-height:230px;padding:28px}.hero h1{font-size:31px;margin:12px 0}.features,.foot{display:none}.form-side{padding:24px 16px}.card{margin-top:-36px;position:relative;z-index:2}}@media(prefers-reduced-motion:reduce){*{transition:none!important}}
